export function InlineName({
  value,
  label,
  editLabel,
  editable = true,
  disabled = false,
  heading,
  completed = false,
  onSave,
  renderActions,
  additionalFields,
  afterName,
  additionalDirty = false,
  className = "",
  compact = false,
  focusFallback,
  readHref,
  onOpen,
}: {
  value: string;
  label: string;
  editLabel: string;
  editable?: boolean;
  disabled?: boolean;
  heading?: "h1" | "h2";
  completed?: boolean;
  onSave: (name: string) => Promise<boolean>;
  additionalFields?: ReactNode;
  afterName?: ReactNode;
  additionalDirty?: boolean;
  className?: string;
  compact?: boolean;
  focusFallback?: RefObject<HTMLButtonElement | null>;
